// GENERATED preamble — every unit in the estate starts here, identically.
// Rejects an envelope whose MAJOR version this unit does not implement, rather than
// half-processing a shape it does not understand.
const SUPPORTED_MAJOR = 1;
const raw = $json.envelope ?? $json;
const v = String(raw.envelope_version ?? '0.0.0');
if (Number(v.split('.')[0]) !== SUPPORTED_MAJOR) {
  throw new Error('VALIDATION_FAILED: envelope_version ' + v + ' is not supported by verify.compliance.screen@1.0.0 (needs ' + SUPPORTED_MAJOR + '.x)');
}
for (const f of ['trace_id', 'tenant_id', 'idempotency_key']) {
  if (!raw[f]) throw new Error('VALIDATION_FAILED: envelope.' + f + ' is required');
}
if (raw.deadline_at && Date.parse(raw.deadline_at) < Date.now()) {
  // Fail fast rather than start work that cannot finish in time.
  throw new Error('TIMEOUT: deadline_at ' + raw.deadline_at + ' already passed before verify.compliance.screen started');
}
return [{ json: {
  ...raw,
  span_id: 'spn_' + Math.random().toString(36).slice(2, 10),
  parent_span_id: raw.span_id ?? null,
  policy: raw.policy ?? {},
  budget: raw.budget ?? {},
  provenance: raw.provenance ?? [],
  _started_at: Date.now(),
  _capability: "verify.compliance.screen",
  _capability_version: "1.0.0"
} }];

// GENERATED telemetry — span_start.
const e = $json;
return [{ json: { ...e, _telemetry: {
  event_id: 'evt_' + Math.random().toString(36).slice(2, 12),
  trace_id: e.trace_id, span_id: e.span_id, parent_span_id: e.parent_span_id,
  tenant_id: e.tenant_id, brand_id: e.brand_id ?? null, vertical: e.vertical ?? null,
  capability: "verify.compliance.screen", capability_version: "1.0.0",
  layer: "terminal", stage: e.stage ?? null,
  event: 'span_start', at: new Date().toISOString()
} } }];

// GENERATED budget guard — injected because verify.compliance.screen declares a cost
// (estimate 1 minor units). A unit that can spend
// money never gets to decide for itself whether it may.
const ESTIMATE = 1;
const e = $json;
const b = e.budget ?? {};
const cap_ = b.cap_minor_units ?? null;
const spent = b.spent_minor_units ?? 0;
if (cap_ !== null && spent + ESTIMATE > cap_) {
  throw new Error('BUDGET_EXCEEDED: ' + (spent + ESTIMATE) + ' would exceed cap ' + cap_ + ' in verify.compliance.screen');
}
let tier = e.policy?.model_tier_cap ?? 'frontier';
const soft = b.soft_limit_pct ?? 0.8;
if (cap_ !== null && spent + ESTIMATE > cap_ * soft) {
  tier = { frontier: 'standard', standard: 'small', small: 'nano', nano: 'nano' }[tier] ?? 'small';
}
return [{ json: { ...e, policy: { ...(e.policy ?? {}), model_tier_cap: tier }, _budget_reserved: ESTIMATE } }];

// Free, instant, and it catches the majority. Run this BEFORE paying a model to think.
const profile = $json;
const env = $('Envelope In').first().json;
const text = [env.payload.title, env.payload.body, env.payload.caption, ...(env.payload.on_screen_text || [])].filter(Boolean).join('\n');
const lower = text.toLowerCase();
const findings = [];

const PATTERNS = {
  absolute_claim: /\b(guaranteed|guarantee[sd]?|100% (effective|safe)|never fails?|always works?|#1 (in|worldwide))\b/i,
  fake_scarcity: /\b(only \d+ left|ends in \d+ (minutes|hours)|last chance ever)\b/i,
  disease_claim: /\b(cures?|treats?|prevents?|heals?|reverses?)\s+\w*\s*(disease|cancer|diabetes|depression|anxiety|arthritis)\b/i,
  outcome_guarantee: /\b(guaranteed|assured|certain)\s+(results?|outcomes?|weight loss|returns?)\b/i,
  return_projection: /\b(\d+%\s*(returns?|gains?|apy|roi)\s*(guaranteed|assured)?)\b/i,
  past_performance_without_disclaimer: /\b(returned|gained|grew)\s+\d+%/i,
  competitor_disparagement: /\b(unlike|better than)\s+(competitor|[A-Z][a-z]+)\b.*\b(broken|useless|scam|terrible)\b/i,
  unsubstantiated_statistic: /\b\d{1,3}(\.\d+)?%\b/,
  protected_class_targeting: /\b(only|perfect for|ideal for)\s+(men|women|christians|muslims|jews|young people|families with children|seniors)\b/i
};

for (const rule of (profile.rules || [])) {
  const re = PATTERNS[rule.test];
  if (!re) continue;
  const m = text.match(re);
  if (m) findings.push({ rule_id: rule.id, severity: rule.severity, test: rule.test, detail: rule.detail || null, evidence: m[0] });
}

for (const term of (env.payload.banned_terms || [])) {
  if (lower.includes(String(term).toLowerCase())) findings.push({ rule_id: 'LEX-BANNED', severity: 'block', test: 'banned_term', evidence: term });
}

for (const d of (profile.required_disclaimers || [])) {
  const present = lower.includes(String(d.text).toLowerCase().slice(0, 40));
  if (!present) findings.push({ rule_id: 'DISC-' + (d.when || 'required'), severity: 'block', test: 'missing_disclaimer', detail: d.text, placement: d.placement });
}

return [{ json: { deterministic_findings: findings, text, needs_model_screen: (profile.review_mode || 'sampled') !== 'none' } }];

